#!/bin/bash
# Build "Kappa.app" and Kappa-<version>-macOS-x64.dmg. Run on an Intel macOS machine/runner
# with python.org Python 3.11 (universal2, macOS 10.9+) and Xcode command line tools.
set -euo pipefail
cd "$(dirname "$0")/.."
ROOT="$(pwd)"
VERSION="${APP_VERSION:-$(python3 -c 'import kappa; print(kappa.__version__)')}"
export APP_VERSION="$VERSION"
export MACOSX_DEPLOYMENT_TARGET=11.0
PY="${PYTHON:-python3}"

rm -rf build dist
mkdir -p build

# 1. icon (assets/icon.png is generated by tools/make_icon.py)
ICONSET=build/Kappa.iconset
mkdir -p "$ICONSET"
for s in 16 32 128 256 512; do
  sips -z $s $s assets/icon.png --out "$ICONSET/icon_${s}x${s}.png" >/dev/null
  sips -z $((s * 2)) $((s * 2)) assets/icon.png --out "$ICONSET/icon_${s}x${s}@2x.png" >/dev/null
done
iconutil -c icns "$ICONSET" -o build/Kappa.icns

# 2. virtual microphone driver
packaging/build_driver.sh "$ROOT/build/drivers"

# 3. app bundle
"$PY" -m PyInstaller --noconfirm --clean --distpath dist --workpath build/pyi packaging/Kappa.spec
APP="dist/Kappa.app"
mkdir -p "$APP/Contents/Resources/drivers" "$APP/Contents/Resources/licenses"
cp -R build/drivers/KappaVoice.driver "$APP/Contents/Resources/drivers/"
cp build/drivers/LICENSE-BlackHole.txt "$APP/Contents/Resources/licenses/"
xattr -cr "$APP"
codesign --force --deep --sign - "$APP"
codesign --verify --deep --strict "$APP"

# 4. checks: Big Sur / Intel compatible binaries + headless self test of the frozen app
"$PY" packaging/check_min_macos.py "$APP" 11.0
"$APP/Contents/MacOS/Kappa" --selftest

# 5. dmg
STAGE=build/dmg
rm -rf "$STAGE"
mkdir -p "$STAGE"
cp -R "$APP" "$STAGE/"
ln -s /Applications "$STAGE/Applications"
cp packaging/README-dmg.txt "$STAGE/Прочти меня.txt"
DMG="dist/Kappa-$VERSION-macOS-x64.dmg"
hdiutil create -volname "Каппа" -srcfolder "$STAGE" -ov -format UDZO -fs HFS+ "$DMG"
hdiutil verify "$DMG"
ls -lh "$DMG"
